import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.HashMap; import java.util.Map; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int[] cost = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6}; int t = Integer.parseInt(br.readLine()); while (t-- > 0) { String n = br.readLine(); int totalMatchsticks = 0; for (char c : n.toCharArray()) { totalMatchsticks += cost[c - '0']; } StringBuilder result = new StringBuilder(); if (totalMatchsticks % 2 != 0) { result.append('7'); totalMatchsticks -= 3; } while (totalMatchsticks > 0) { result.append('1'); totalMatchsticks -= 2; } System.out.println(result.toString()); } } }